/**
 * Legibility bounds: the smallest text, the tightest lines and gaps, the
 * smallest controls, and the leaves a reader cannot read in full. Measured
 * over the WHOLE page in the same pass as the ledger, and attached to every
 * report, so that a change which saves scroll by shrinking text is visible
 * beside the saving.
 *
 * - `fontPx` (minimum and 10th percentile) and `lineHeightRatio` (line
 *   height ÷ font size, minimum and 10th percentile) of the answer and value
 *   leaves whose text is drawn. A leaf whose `chars` is an aria-label / title
 *   the serializer substituted for absent text (`charsDrawn: false`) draws no
 *   glyph at its font size, so it is excluded, and counted.
 * - `gapEm`: the smallest vertical gap from an answer or value leaf to the
 *   next painted leaf below it in its column, in that leaf's em.
 * - `controls`: the smallest side of a control leaf, and the smallest gap
 *   between two control leaves that do not overlap.
 * - `truncated` and `occluded`: the leaves cut short or covered.
 *
 * The 10th percentile is nearest-rank: the value at position `ceil(0.1 · n)`
 * of the ascending list. Every list is capped and reports `shown`, `total`
 * and `truncated`.
 *
 * Plan: 2026-11-23-ui-bridge-measures-information-density-as-reach-per-role-and-plans-the-change (Phase 5).
 */

import type { DensityLedgerKind } from './ledger';
import type { DensityCapture, DensityItem, DensityRect } from './schema';
import { densitySameColumn } from './structure';
import type { DensityUnknownQuantity } from './repeats';

/** The longest list of leaves a bound reports; the rest is counted. */
export const DENSITY_BOUND_LIST_CAP = 20;

/** A capped list of ids. */
export interface DensityCappedIds {
  shown: number;
  total: number;
  truncated: boolean;
  ids: string[];
}

/** A bound over a set of leaves: its minimum, 10th percentile, and the leaves AT the minimum. */
export interface DensityBoundValue {
  min: number;
  p10: number;
  /** Leaves measured. */
  of: number;
  atMin: DensityCappedIds;
}

export interface DensityBounds {
  /** The answer and value leaves the text bounds read, and those they could not. */
  textLeaves: {
    considered: number;
    /** `charsDrawn: false`: the counted text is a label fallback or hidden text. */
    undrawn: number;
    /** `charsDrawn: null`. */
    drawnUnknown: number;
    fontUnknown: number;
    lineHeightUnknown: number;
    /** Leaves left out because their visibility is unknown. */
    visibilityUnknown: number;
    /** Items whose leaf status is unknown (redacted text): never read by any bound. */
    leafUnknown: number;
  };
  fontPx: DensityBoundValue | DensityUnknownQuantity;
  lineHeightRatio: DensityBoundValue | DensityUnknownQuantity;
  gapEm: { min: number; of: number; atMin: DensityCappedIds } | DensityUnknownQuantity;
  controls: {
    count: number;
    minSidePx: { value: number; atMin: DensityCappedIds } | DensityUnknownQuantity;
    minGapPx: { value: number; between: [string, string] } | DensityUnknownQuantity;
  };
  truncated: DensityCappedIds & { list: Array<{ id: string; recoverable: boolean | null }> };
  occluded: DensityCappedIds;
}

function capped(ids: string[], cap: number): DensityCappedIds {
  const shown = ids.slice(0, Math.max(0, cap));
  return {
    shown: shown.length,
    total: ids.length,
    truncated: shown.length < ids.length,
    ids: shown,
  };
}

/** Nearest-rank percentile of an ascending list. */
function percentile(sorted: readonly number[], p: number): number {
  const rank = Math.max(1, Math.ceil(p * sorted.length));
  return sorted[rank - 1];
}

function boundOf(
  values: Array<{ id: string; v: number }>,
  cap: number,
  none: string
): DensityBoundValue | DensityUnknownQuantity {
  if (values.length === 0) return { unknown: 'input_missing', reason: none };
  const sorted = values.map((x) => x.v).sort((a, b) => a - b);
  const min = sorted[0];
  return {
    min,
    p10: percentile(sorted, 0.1),
    of: values.length,
    atMin: capped(
      values.filter((x) => x.v === min).map((x) => x.id),
      cap
    ),
  };
}

function isPainted(item: DensityItem): boolean {
  return item.visibility === 'rendered' || item.visibility === 'occluded';
}

/** Separation of two rects: the larger of the horizontal and vertical gaps, 0 when they touch or overlap. */
function separation(a: DensityRect, b: DensityRect): number {
  const dx = Math.max(0, Math.max(a.x, b.x) - Math.min(a.x + a.w, b.x + b.w));
  const dy = Math.max(0, Math.max(a.y, b.y) - Math.min(a.y + a.h, b.y + b.h));
  return Math.max(dx, dy);
}

/**
 * The bounds of one capture. `kinds` is each leaf's ledger kind (answers
 * already marked); `placed` the rects at scroll 0 (`densityPlacedRects`).
 */
export function densityBounds(
  capture: DensityCapture,
  kinds: ReadonlyMap<string, DensityLedgerKind>,
  placed: ReadonlyMap<string, DensityRect>,
  cap: number = DENSITY_BOUND_LIST_CAP,
  leafUnknown: readonly string[] = []
): DensityBounds {
  const leaves = capture.items.filter((i) => kinds.has(i.id));
  const visibilityUnknown = leaves.filter((i) => i.visibility === null).length;
  const painted = leaves.filter((i) => isPainted(i) && placed.has(i.id));

  // ---- text ----
  const text = painted.filter((i) => {
    const k = kinds.get(i.id);
    return (k === 'answer' || k === 'value') && (i.chars === null || i.chars > 0);
  });
  const counts = {
    considered: text.length,
    undrawn: 0,
    drawnUnknown: 0,
    fontUnknown: 0,
    lineHeightUnknown: 0,
    visibilityUnknown,
    leafUnknown: leafUnknown.length,
  };
  const fonts: Array<{ id: string; v: number }> = [];
  const ratios: Array<{ id: string; v: number }> = [];
  const drawn: DensityItem[] = [];
  for (const i of text) {
    if (i.charsDrawn === false) {
      counts.undrawn++;
      continue;
    }
    if (i.charsDrawn === null) {
      counts.drawnUnknown++;
      continue;
    }
    drawn.push(i);
    if (i.fontPx === null) {
      counts.fontUnknown++;
      continue;
    }
    fonts.push({ id: i.id, v: i.fontPx });
    if (i.lineHeightPx === null) counts.lineHeightUnknown++;
    else ratios.push({ id: i.id, v: i.lineHeightPx / i.fontPx });
  }

  // ---- gap below each text leaf, in its em ----
  const gaps: Array<{ id: string; v: number }> = [];
  for (const i of drawn) {
    if (i.fontPx === null) continue;
    const r = placed.get(i.id)!;
    const bottom = r.y + r.h;
    let nearest = Infinity;
    for (const o of painted) {
      if (o === i) continue;
      const q = placed.get(o.id)!;
      if (q.y < bottom || !densitySameColumn(r, q)) continue;
      nearest = Math.min(nearest, q.y - bottom);
    }
    if (Number.isFinite(nearest)) gaps.push({ id: i.id, v: nearest / i.fontPx });
  }
  let gapEm: DensityBounds['gapEm'];
  if (gaps.length === 0) {
    gapEm = {
      unknown: 'input_missing',
      reason:
        'no drawn answer or value leaf with a font size has a painted leaf below it in its column',
    };
  } else {
    const min = Math.min(...gaps.map((g) => g.v));
    gapEm = {
      min,
      of: gaps.length,
      atMin: capped(
        gaps.filter((g) => g.v === min).map((g) => g.id),
        cap
      ),
    };
  }

  // ---- controls ----
  const controls = painted.filter((i) => kinds.get(i.id) === 'control' || i.interactive);
  let minSidePx: DensityBounds['controls']['minSidePx'];
  if (controls.length === 0) {
    minSidePx = { unknown: 'input_missing', reason: 'no painted control leaf' };
  } else {
    const sides = controls.map((c) => {
      const r = placed.get(c.id)!;
      return { id: c.id, v: Math.min(r.w, r.h) };
    });
    const value = Math.min(...sides.map((s) => s.v));
    minSidePx = {
      value,
      atMin: capped(
        sides.filter((s) => s.v === value).map((s) => s.id),
        cap
      ),
    };
  }
  let minGapPx: DensityBounds['controls']['minGapPx'] = {
    unknown: 'input_missing',
    reason: 'fewer than two painted control leaves that do not overlap',
  };
  let bestGap = Infinity;
  for (let a = 0; a < controls.length; a++) {
    const ra = placed.get(controls[a].id)!;
    for (let b = a + 1; b < controls.length; b++) {
      const rb = placed.get(controls[b].id)!;
      const overlap =
        ra.x < rb.x + rb.w && rb.x < ra.x + ra.w && ra.y < rb.y + rb.h && rb.y < ra.y + ra.h;
      if (overlap) continue;
      const g = separation(ra, rb);
      if (g < bestGap) {
        bestGap = g;
        minGapPx = { value: g, between: [controls[a].id, controls[b].id] };
      }
    }
  }

  // ---- truncated and occluded ----
  const truncatedLeaves = painted.filter((i) => i.truncated === true);
  const truncatedIds = capped(
    truncatedLeaves.map((i) => i.id),
    cap
  );

  return {
    textLeaves: counts,
    fontPx: boundOf(fonts, cap, 'no drawn answer or value leaf carries a font size'),
    lineHeightRatio: boundOf(
      ratios,
      cap,
      'no drawn answer or value leaf carries both a font size and a line height'
    ),
    gapEm,
    controls: { count: controls.length, minSidePx, minGapPx },
    truncated: {
      ...truncatedIds,
      list: truncatedLeaves
        .slice(0, truncatedIds.shown)
        .map((i) => ({ id: i.id, recoverable: i.recoverable })),
    },
    occluded: capped(
      painted.filter((i) => i.visibility === 'occluded').map((i) => i.id),
      cap
    ),
  };
}
